'use strict';
const $=s=>document.querySelector(s),fmt=n=>n.toLocaleString('en-US');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9+#.]+/g,' ').trim();
const categories=[
 ['frontend','Frontend & web',/\b(html|css|javascript|typescript|react|vue|angular|svelte|next\.?js|frontend|front end|browser|dom|web design|web development|tailwind|bootstrap|responsive|webpack|vite|jquery)\b/],
 ['backend','Backend & APIs',/\b(backend|back end|api|apis|node\.?js|express|django|flask|fastapi|rails|laravel|php|graphql|rest|nestjs|server)\b/],
 ['data','Data & databases',/\b(data|database|databases|sql|mysql|postgres|postgresql|mongodb|pandas|numpy|redis|sqlite|analytics|visualization|excel|spreadsheet|statistics)\b/],
 ['ai','AI & machine learning',/\b(ai|artificial intelligence|machine learning|deep learning|neural|llm|llms|gpt|chatgpt|langchain|tensorflow|pytorch|mcp|rag|hugging|nlp|agents?|diffusion)\b/],
 ['devops','Cloud & DevOps',/\b(devops|cloud|aws|azure|docker|kubernetes|k8s|ci cd|deployment|deploy|linux|bash|nginx|terraform|gke|serverless|infrastructure|jenkins|github actions)\b/],
 ['design','Design & accessibility',/\b(design|accessibility|accessible|a11y|wcag|typography|color|figma|ux|ui|usability|user experience|animation)\b/],
 ['security','Security',/\b(security|cybersecurity|authentication|authorization|oauth|webauthn|passkey|encryption|cryptography|hacking|vulnerabilit\w*|password|jwt|penetration)\b/],
 ['languages','Languages & fundamentals',/\b(python|java|javascript|typescript|golang|rust|c\+\+|c#|ruby|swift|kotlin|programming|algorithm|data structures|recursion|function|variable|object oriented|oop|compiler|computer science)\b/],
 ['mobile','Mobile & games',/\b(android|ios|mobile|flutter|react native|swift|kotlin|game|games|gaming|unity|unreal|godot)\b/],
 ['practice','Testing & code quality',/\b(test|tests|testing|tdd|debug|debugging|clean code|refactor|quality|playwright|cypress|jest|performance|optimization|optimizing|best practices|code review)\b/],
 ['career','Career & learning',/\b(career|interview|job|jobs|hired|resume|portfolio|learn to code|learning to code|beginner|beginners|study|mentorship|bootcamp|salary|developer habits|productivity)\b/],
 ['tools','Tools & collaboration',/\b(git|github|vscode|vs code|editor|terminal|command line|open source|npm|package|documentation|readme|technical writing|collaboration)\b/],
 ['other','Other subjects',null]
];
let articles=[],manifest={},page=1,selectedCategory='',filtered=[],pageSize=40,opener=null;
const state={query:'',topic:'',year:'',sort:'newest',metadata:false};
const params=new URLSearchParams(location.search);state.query=params.get('q')||'';selectedCategory=params.get('category')||'';state.topic=params.get('topic')||'';state.year=params.get('year')||'';state.sort=['newest','oldest','az'].includes(params.get('sort'))?params.get('sort'):'newest';state.metadata=params.get('metadata')==='1';
function openAbout(e){e?.preventDefault();opener=document.activeElement;$('#about').showModal();$('#about-close').focus()}
$('#about-open').addEventListener('click',openAbout);$('#coverage-open').addEventListener('click',openAbout);$('#category-method').addEventListener('click',openAbout);$('#about-close').onclick=()=>$('#about').close();$('#about').addEventListener('close',()=>opener?.focus());$('#about').addEventListener('click',e=>{if(e.target===$('#about')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#categories-toggle').onclick=()=>{const expanded=$('#categories-toggle').getAttribute('aria-expanded')!=='true';$('#categories-toggle').setAttribute('aria-expanded',expanded);$('#categories-toggle').textContent=expanded?'Hide categories':'Show categories';$('#categories').classList.toggle('expanded',expanded)};
function datestr(date){return date?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(date)):'Date unavailable'}
function categoryName(){return categories.find(c=>c[0]===selectedCategory)?.[1]||'All articles'}
function syncURL(){const p=new URLSearchParams();if(state.query)p.set('q',state.query);if(selectedCategory)p.set('category',selectedCategory);if(state.topic)p.set('topic',state.topic);if(state.year)p.set('year',state.year);if(state.sort!=='newest')p.set('sort',state.sort);if(state.metadata)p.set('metadata','1');history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+location.hash)}
function renderCategories(){const counts=Object.fromEntries(categories.map(c=>[c[0],articles.filter(a=>a.categories.includes(c[0])).length]));$('#categories').innerHTML=`<button data-category="" aria-pressed="${!selectedCategory}">All articles<span>${fmt(articles.length)}</span></button>`+categories.map(c=>`<button data-category="${c[0]}" aria-pressed="${selectedCategory===c[0]}">${c[1]}<span>${fmt(counts[c[0]])}</span></button>`).join('')}
let topicCategory=null;
function refreshTopics(){
 if(topicCategory===selectedCategory)return;
 const counts=new Map();
 for(const article of articles){
  if(selectedCategory&&!article.categories.includes(selectedCategory))continue;
  for(const topic of article.tags)counts.set(topic,(counts.get(topic)||0)+1);
 }
 if(state.topic&&!counts.has(state.topic))state.topic='';
 $('#topic').innerHTML='<option value="">All topics</option>'+[...counts].sort((a,b)=>a[0].localeCompare(b[0])).map(([topic,count])=>`<option value="${escape(topic)}">${escape(topic)} (${fmt(count)})</option>`).join('');
 $('#topic').value=state.topic;
 topicCategory=selectedCategory;
}
function update(resetPage=true){refreshTopics();if(resetPage)page=1;const tokens=clean(state.query).split(' ').filter(Boolean);filtered=articles.filter(a=>(!selectedCategory||a.categories.includes(selectedCategory))&&(!state.topic||a.tags.includes(state.topic))&&(!state.year||a.date?.startsWith(state.year))&&(!state.metadata||a.metadataSource==='public-listing')&&tokens.every(t=>a.search.includes(t)));filtered.sort((a,b)=>{if(state.sort==='az')return (a.title||a.url).localeCompare(b.title||b.url);if(!a.date||!b.date)return a.date?-1:b.date?1:a.url.localeCompare(b.url);return state.sort==='newest'?b.date.localeCompare(a.date):a.date.localeCompare(b.date)});renderResults();syncURL();$('#clear-search').hidden=!state.query;$('#view-title').textContent=categoryName();$('#result-count').textContent=`${fmt(filtered.length)} ${filtered.length===1?'result':'results'}${filtered.length!==articles.length?' of '+fmt(articles.length)+' records':''}`;$('#active-filters').textContent=[state.topic&&'Topic: '+state.topic,state.year&&'Year: '+state.year,state.query&&'Search: '+state.query].filter(Boolean).join(' · ')}
const ext='<svg class="external" viewBox="0 0 24 24" aria-hidden="true"><path d="M14 4h6v6M20 4 10 14M10 4H4v16h16v-6"/></svg><span class="sr-only"> (opens in a new tab)</span>';
function renderResults(){const totalPages=Math.max(1,Math.ceil(filtered.length/pageSize));page=Math.max(1,Math.min(page,totalPages));const slice=filtered.slice((page-1)*pageSize,page*pageSize);$('#results').innerHTML=slice.length?slice.map(a=>`<article class="article"><div class="article-top">${a.tags.length?`<button class="topic-link" data-topic="${escape(a.tags[0])}" aria-label="Filter topic: ${escape(a.tags[0])}">#${escape(a.tags[0])}</button>`:''}${a.metadataSource==='sitemap-only'?'<span class="record-type">URL-only record · metadata not collected</span>':''}</div><h3><a href="${escape(a.url)}" target="_blank" rel="noopener">${escape(a.title||'Article metadata unavailable')}${ext}</a></h3>${!a.title?`<p class="article-url">${escape(decodeURIComponent(new URL(a.url).pathname.replace('/news/','')))}</p>`:''}<p class="article-meta"><span>${escape(a.author||'Author not shown in listing')}</span><time${a.date?` datetime="${escape(a.date)}"`:''}>${datestr(a.date)}</time>${!a.inSitemap?'<span>Listing only · absent from sitemap snapshot</span>':''}</p></article>`).join(''):'<div class="empty"><h3>No matching articles</h3><p>Try fewer words, a broader topic, or clear the filters.</p><button id="empty-reset">Clear all filters</button></div>';$('#previous').disabled=page===1;$('#next').disabled=page===totalPages;$('#page-number').textContent=`Page ${fmt(page)} of ${fmt(totalPages)}`;$('#empty-reset')?.addEventListener('click',reset)}
function reset(){clearTimeout(timer);const fromEmpty=document.activeElement?.id==='empty-reset';Object.assign(state,{query:'',topic:'',year:'',sort:'newest',metadata:false});selectedCategory='';$('#search').value='';$('#topic').value='';$('#year').value='';$('#sort').value='newest';$('#metadata-only').checked=false;renderCategories();update();if(fromEmpty)$('#search').focus()}
$('#reset').onclick=reset;$('#search-form').onsubmit=e=>{e.preventDefault();clearTimeout(timer);state.query=$('#search').value.trim();update()};let timer;$('#search').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{state.query=$('#search').value.trim();update()},180)});$('#clear-search').onclick=()=>{clearTimeout(timer);state.query='';$('#search').value='';update();$('#search').focus()};['topic','year','sort'].forEach(id=>$('#'+id).onchange=()=>{state[id]=$('#'+id).value;update()});$('#metadata-only').onchange=()=>{state.metadata=$('#metadata-only').checked;update()};$('#categories').onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;selectedCategory=b.dataset.category;renderCategories();update();const next=[...document.querySelectorAll('[data-category]')].find(x=>x.dataset.category===selectedCategory);next?.focus()};$('#results').onclick=e=>{const b=e.target.closest('[data-topic]');if(b){state.topic=b.dataset.topic;$('#topic').value=state.topic;update();$('#topic').focus()}};$('#previous').onclick=()=>{page--;update(false);$('#results').focus()};$('#next').onclick=()=>{page++;update(false);$('#results').focus()};
async function init(){try{const r=await fetch('articles.json');if(!r.ok)throw Error('Index unavailable');const d=await r.json();manifest=d.manifest;articles=d.articles.map(a=>{const content=clean([a.title,a.url,...a.tags].join(' '));const group=categories.filter(c=>c[2]?.test(content)).map(c=>c[0]);return {...a,categories:group.length?group:['other'],search:clean([a.title,a.url,a.author,...a.tags].join(' '))}});if(!categories.some(c=>c[0]===selectedCategory))selectedCategory='';const topics=new Map();for(const a of articles)for(const t of a.tags)topics.set(t,(topics.get(t)||0)+1);$('#topic').innerHTML='<option value="">All topics</option>'+[...topics].sort((a,b)=>a[0].localeCompare(b[0])).map(([t,n])=>`<option value="${escape(t)}">${escape(t)} (${fmt(n)})</option>`).join('');const years=[...new Set(articles.filter(a=>a.date).map(a=>a.date.slice(0,4)))].sort().reverse();$('#year').innerHTML='<option value="">All years</option>'+years.map(y=>`<option>${y}</option>`).join('');if(!topics.has(state.topic))state.topic='';if(!years.includes(state.year))state.year='';$('#search').value=state.query;$('#topic').value=state.topic;$('#year').value=state.year;$('#sort').value=state.sort;$('#metadata-only').checked=state.metadata;$('#total-number').textContent=fmt(manifest.indexed);$('#metadata-number').textContent=fmt(topics.size);$('#topics-number').textContent=years.length?years.at(-1)+'–'+years[0]:'Unavailable';$('#snapshot').innerHTML=`Snapshot: ${datestr(manifest.collected+'T12:00:00Z')} · ${manifest.sitemapOnly?fmt(manifest.sitemapOnly)+' URL-only records':'All sitemap URLs matched to listing metadata'}${manifest.listingOnly?' · '+fmt(manifest.listingOnly)+' listing-only records':''}. <button id="snapshot-about">See coverage</button>`;$('#snapshot-about').onclick=openAbout;$('#coverage').innerHTML=`<table class="coverage-table"><tbody>${[['Unique post sitemap URLs',manifest.sitemapCount],['Catalog records',articles.length],['Records with listing metadata',manifest.withMetadata],['Sitemap URLs without listing metadata',manifest.sitemapOnly],['Listing records absent from sitemap',manifest.listingOnly],['Listing pages collected',manifest.pagesFetched],['Listings without an author credit',articles.filter(a=>!a.author).length],['Listings without a primary topic',articles.filter(a=>!a.tags.length).length]].map(([l,n])=>`<tr><th scope="row">${l}</th><td>${fmt(n)}</td></tr>`).join('')}</tbody></table><p class="coverage-note">Collected ${datestr(manifest.collected+'T12:00:00Z')}. ${manifest.sitemapOnly?'Metadata coverage is incomplete. URL-only records are retained and clearly labeled.':'Every sitemap URL has matching listing metadata.'} ${manifest.errors.length?`${manifest.errors.length} listing requests could not be completed.`:''} Matching listing metadata does not mean every field is present. Missing author credits and primary topics are retained as missing, not inferred. The sitemap and listings may reflect different publication moments. The sitemap’s last-modified dates are not treated as publication dates.</p>`;renderCategories();update()}catch(e){$('#results').innerHTML='<div class="empty"><h3>The collection could not load</h3><p>Reload the page to try again.</p><button id="retry">Reload collection</button></div>';$('#retry').onclick=()=>location.reload();$('#snapshot').textContent='Collection unavailable. Please reload.';console.error(e)}}init();
